-- Procedure structure for `sp_correctstockold`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_correctstockold`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_correctstockold`()
begin
	truncate table stocktbl;

	
	select pid,qty,a.eid,1,a.edate,prate,srate,wrate,mrp,SupplierId,Barcode from purchasedetails a,purchasemaster b
where b.eid=a.eid;


	select pid,qty,a.eid,2,a.edate,rate,CustomerId,PRate,Mrp,WRate,Barcode from saledetails a,salemaster b
where a.eid=b.eid;


	select pid,qty,a.eid,5,a.edate,rate,SupplierId,PRate,Mrp,WRate,Barcode from purchasereturndetails a,purchasereturnmaster b
where a.eid=b.eid;


	select pid,qty,a.eid,6,a.edate,rate,customerId,PRate,Mrp,WRate,Barcode from salesreturndetails a,salesreturnmaster b
where a.eid=b.eid;

  

	select pid,qty,a.billno,10,b.dt,mrate,srate,wrate,mrp,barcode from manufacturedetails a,manufacturemaster b
where a.BillNo=b.billno;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_CustomerBillOutstanding`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_CustomerBillOutstanding`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_CustomerBillOutstanding`(in endDt Date)
begin
	set @qry=concat('select 0 Sno,b.name CusName,a.Eid SalesBillNo,c.Eid ReceiptNo,a.Edate SaleDt,c.dt ReceiptDt,DATEDIFF(c.Dt,a.EDate) Days,a.TotalAmount TotalAmount,
	c.Amount Recv,0.00 Balance
	from salemaster a,ledger b,receiptbybill c
	where a.CustomerId=b.id and b.ID=c.Cid
	and a.Eid=c.EntryNo and a.mode=1
	and a.EDate<=\'',endDt,'\'
	GROUP BY b.id,a.eid,c.eid
	order by a.EDate,c.Dt ');
		
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	
End
;;
DELIMITER ;

