begin
call sp_correctstock();
	set @qry=concat('select 0 Sno,c.name Name,d.StckName EntryFrm,Date,Efrm EntryNo,Inqty,OutQty,0.00 Balance
From Product A,stocktbl b,ledger c,vouchertype d where a.id=b.pid 
and a.Name like \'',PName,'\'
and b.date between \'',frm,'\' and \'',too,'\' 
and c.ID=b.lid and b.Efrm=d.StckType
ORDER BY Date,Efrm,d.StckType');
PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;


end
;;
