-- ----------------------------
-- Procedure structure for `sp_LedgerHistory`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_LedgerHistory`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_LedgerHistory`(in Mode int,in grp int,in Lid int,in frm date,in too date)
begin

	call sp_correctStock();
	
	if(Mode=1 and grp=0)then
	set @qry=concat('select Date(a.date) Dt,a.eid BillNo,c.Name ProductName,InQty Purchase,outqty PReturn,
		round(inQty * a.pRate,2) PurchaseAmount,Round(outQty * a.SRate,2)ReturnAmount
		from stocktbl a,Ledger b,Product c
		where a.Lid=b.id and c.id=a.Pid and lid=',Lid,'
		and a.date between \'',frm,'\' and \'',too,'\'
		order by a.Date,a.eid,a.Efrm');

		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;

	elseif(Mode=1 and grp=1)then
	set @qry=concat('select Date(a.date) Dt,a.eid BillNo,c.Name ProductName,inQty Purchase,outqty PReturn,
		round(inQty * a.pRate,2) PurchaseAmount,Round(outQty * a.pRate,2)ReturnAmount
		from stocktbl a,Ledger b,Product c
		where a.Lid=b.id and c.id=a.Pid and lid=',Lid,'
		and a.date between \'',frm,'\' and \'',too,'\'
		order by a.Date,a.eid,a.Efrm');
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	elseif(Mode=2 and grp=0)then
		set @qry=concat('select Date(a.date) Dt,a.eid BillNo,c.Name ProductName,OutQty Sales,inqty SReturn,
		round(OutQty * a.SRate,2) SalesAmount,Round(inQty * a.SRate,2)ReturnAmount
		from stocktbl a,Ledger b,Product c
		where a.Lid=b.id and c.id=a.Pid and lid=',Lid,'
		and a.date between \'',frm,'\' and \'',too,'\'
		order by a.Date,a.eid,a.Efrm');
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	elseif(Mode=2 and grp=1)then
		set @qry=concat('select c.Name ProductName,sum(OutQty) Sales,sum(inqty) SReturn,
		round(sum(OutQty) * avg(a.SRate),2) SalesAmount,Round(sum(inQty) * avg(a.SRate),2)ReturnAmount
		from stocktbl a,Ledger b,Product c
		where a.Lid=b.id and c.id=a.Pid and lid=',Lid,'
		and a.date between \'',frm,'\' and \'',too,'\'
		group by c.id');
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	
	end if;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `SP_LoadDailyDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_LoadDailyDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_LoadDailyDetails`(in Dt Date)
begin

	declare Cnt int DEFAULT 0;
	
	set @qry=concat('Select Count(*) into @Cnt From daybookdetails');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
		if(@Cnt=0)then
		set @qry='Select 0 Sno,\' \' MNo,a.id Pid,a.Name Name,
					\' \'Clr,
					0.0 WarpQty,0.0 WarpRate,0.0 WarpAmt,
					0.0 BoxQty,0.0 BoxRate,0.0 BoxAmt,
					0.0 DubianQty,0.0 DubianRate,0.0 DubianAmt,
					0.0 JariQty,0.0 JariRate,0.0 JariAmt,
					0.0 Salary,0.0 TotMRate,0.0 TotSRate,0.0 Profit
					from product a 
 ';
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	else
set @qry=concat('Select Count(*) into @Cnt From daybookdetails where Dt=\'',Dt,'\' ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;

		if(@Cnt=0)then

		set @qry=concat('Select Count(*) into @Cnt From daybookdetails where  dt=DATE_SUB(\'',Dt,'\',INTERVAL 1 day) ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
if(@Cnt=0)THEN
set @qry='Select 0 Sno,\' \' MNo,a.id Pid,a.Name Name,
					\' \'Clr,
					0.0 WarpQty,0.0 WarpRate,0.0 WarpAmt,
					0.0 BoxQty,0.0 BoxRate,0.0 BoxAmt,
					0.0 DubianQty,0.0 DubianRate,0.0 DubianAmt,
					0.0 JariQty,0.0 JariRate,0.0 JariAmt,
					0.0 Salary,0.0 TotMRate,0.0 TotSRate,0.0 Profit
					from product a 
 ';
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
ELSE
set @qry=Concat('Select 0 Sno,MNo,a.id Pid,a.Name Name,
					Clr,
					WarpQty,WarpRate,WarpAmt,
					BoxQty,BoxRate,BoxAmt,
					DubianQty,DubianRate,DubianAmt,
					JariQty,JariRate,JariAmt,
					Salary,TotMRate,TotSRate,Profit
					from product a left OUTER join daybookdetails b  
					 on a.id=b.pid 
					 where b.dt=DATE_SUB(\'',Dt,'\',INTERVAL 1 day) ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
end if;
		
		
		else
		set @qry=Concat('Select 0 Sno,MNo,a.id Pid,a.Name Name,
					Clr,
					WarpQty,WarpRate,WarpAmt,
					BoxQty,BoxRate,BoxAmt,
					DubianQty,DubianRate,DubianAmt,
					JariQty,JariRate,JariAmt,
					Salary,TotMRate,TotSRate,Profit
					from product a left OUTER join daybookdetails b  
					 on a.id=b.pid 
					 where b.dt=\'',Dt,'\' ');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
		end if;
	end if;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_LoadLedgerForVoucher`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_LoadLedgerForVoucher`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_LoadLedgerForVoucher`(in Lid varchar(10),in Lid1 varchar(10))
begin
	
	set @qry=concat('Select a.id Id,a.Name Name,if(Sum(Dr)-Sum(Cr)=null,0,Sum(Dr)-Sum(Cr))Balance,a.INFO7 GstNo,a.info8 PhoneNo 
from ledger a  LEFT OUTER JOIN ledgerentry b on a.id=b.CrLid
where  a.under_id like \'',Lid,'\' ');
if(Lid1<>0)THEN
	set @qry=CONCAT(@qry,' or a.UNDER_ID like \'',Lid1,'\' ');
end if;
set @qry=CONCAT(@qry,' GROUP BY a.id ');

		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_LoadSupplierdealt`
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_LoadSupplierdealt`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_LoadSupplierdealt`(in sName text)
begin

	set @qry=concat('select 0 Sno,a.InvoiceNo BillNo,a.edate Dt,c.name SupName,c.info4 Area,
a.TotalAmount-if(d.totalamount is not null,d.TotalAmount,0)TotalAmount,
DATEDIFF(CURDATE(),a.EDate)Days,
	if(Sum(b.Amount) is null,0,sum(b.Amount))Payment,
a.TotalAmount-if(d.totalamount is not null,d.TotalAmount,0)-if(Sum(b.Amount) is null,0,sum(b.Amount)) Balance
from ledger c,purchasemaster a LEFT OUTER JOIN Payment b on a.InvoiceNo=b.BillNo  LEFT OUTER JOIN rpurchasemaster d on a.InvoiceNo=d.InvoiceNo
where 
c.id=a.sid and c.name like \'',sName,'\' and a.mode=1
GROUP BY cast(a.Eid as UNSIGNED) 
having balance>=1;');

PREPARE s1 FROM @qry;
EXECUTE s1;
DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `sp_LoadSupplierdealt1`
