CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_MonthlyFastMovingItem`(in frm Date,in too date)
begin

	Set @qry=concat('Select A.Name Name,Sum(Qty) Qty,Sum(InQty)-Sum(OutQty)Balance From saledetails b,Product a LEFT OUTER JOIN stocktbl c 
	on a.id=c.pid
	where a.Id=b.pid 
	and 
	b.edate between \'',frm,'\' and \'',too,'\' 
	group by a.id ORDER BY Qty desc limit 10;');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
