-- ----------------------------
-- Procedure structure for `Sp_PaymentByAllBill`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_PaymentByAllBill`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_PaymentByAllBill`(in Sid int)
begin

	Set @qry=concat('Select b.Eid EntryNo,b.EDate Dt,b.InvoiceNo InvoiceNo,
if(b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.edate)) `Days`,b.InvoiceDt InvoiceDt,
b.TotalAmount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  purchasemaster b LEFT OUTER JOIN paymentbybill a on a.EntryNo=b.Eid and b.SupplierId=a.sid
where  b.`Mode`=1  and b.SupplierId=\'',Sid,'\' GROUP BY b.Eid 
union(
Select b.BillNo EntryNo,b.Dt Dt,' ' InvoiceNo,
if(b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,datediff(CURDATE(),b.DT)) `Days`,\'2017-04-01\' InvoiceDt,
b.Amount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  opbalbill b LEFT OUTER JOIN paymentbybill a on a.EntryNo=b.billno and b.lid=a.sid
where  b.lid=\'',Sid,'\' GROUP BY b.BillNo )');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_PaymentByBill`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_PaymentByBill`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_PaymentByBill`(in Sid int)
begin

	Set @qry=concat('Select b.Eid EntryNo,b.EDate Dt,b.InvoiceNo InvoiceNo,
if(b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.edate)) `Days`,b.InvoiceDt InvoiceDt,
b.TotalAmount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  purchasemaster b LEFT OUTER JOIN paymentbybill a on a.EntryNo=b.Eid and b.SupplierId=a.sid
where  b.`Mode`=1  and b.SupplierId=\'',Sid,'\' GROUP BY b.Eid having Balance>=1 
union(
Select b.BillNo EntryNo,b.Dt Dt,' ' InvoiceNo,
if(b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.DT)) `Days`,\'2017-04-01\' InvoiceDt,
b.Amount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  opbalbill b LEFT OUTER JOIN paymentbybill a on a.EntryNo=b.billno and b.lid=a.sid
where  b.lid=\'',Sid,'\' GROUP BY b.BillNo having Balance>=1)');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

