-- ----------------------------
-- Procedure structure for `Sp_PurchaseMasterDisplayhsn`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_PurchaseMasterDisplayhsn`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_PurchaseMasterDisplayhsn`(in Frm Date,in too Date)
begin


	set @qry=concat('Select 0 Sno,C.Eid BillNo,c.EDate Dt,Cus.NAME NAME,Cus.INFO6 GSTNO,b.Name ProductName ,b.Hsn HSN,a.Qty Qty,a.OriPrate,round((a.OriPrate*a.Qty),2) Amount,
d.name Tax,a.CgstAmount Cgst,a.SgstAmount Sgst,a.IgstAmount Igst,a.DiscPerc,a.DiscAmount
from ledger d, product b,purchasedetails a,purchasemaster c left outer join ledger Cus on c.SupplierId=cus.ID
where a.Pid=b.id and 
a.eid=c.eid  
and d.ID=a.TaxId
and A.EDate between \'',Frm,'\'  and  \'',Too,'\'  Order By c.eid ');

	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;

End
;;
DELIMITER ;

