-- ----------------------------
-- Procedure structure for `Sp_ReceiptByAllBill`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_ReceiptByAllBill`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_ReceiptByAllBill`(in Sid int)
begin

	Set @qry=concat('Select b.Eid EntryNo,b.EDate Dt,
if(b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.edate)) `Days`,
b.TotalAmount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  salemaster b LEFT OUTER JOIN receiptbybill a on a.EntryNo=b.Eid and b.customerid=a.cid
where  b.`Mode`=1  and b.customerid=\'',Sid,'\' GROUP BY b.Eid 
union(
Select b.BillNo EntryNo,b.Dt Dt,
if(b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.DT)) `Days`,
b.Amount TotalAmount,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  opbalbill b LEFT OUTER JOIN Receiptbybill a on a.EntryNo=b.billno and b.lid=a.cid
where  b.lid=\'',Sid,'\' GROUP BY b.BillNo )');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for `Sp_ReceiptByBill`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_ReceiptByBill`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_ReceiptByBill`(in Sid int)
begin

	Set @qry=concat('Select b.Eid EntryNo,b.EDate Dt,
if(b.TotalAmount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.edate)) `Days`,
b.TotalAmount TotalAmount,if(c.TotalAmount is not Null,C.TotalAmount,0)SalesReturn,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.TotalAmount - (if(Sum(a.Amount) is null,0,Sum(a.Amount))+if(c.TotalAmount is not Null,C.TotalAmount,0)) Balance
From  salemaster b LEFT OUTER JOIN receiptbybill a on a.EntryNo=b.Eid and b.customerid=a.cid left outer join salesreturnmaster c on b.eid=c.invoiceNo 
and b.customerid=c.customerId
where  b.`Mode`=1  and b.customerid=\'',Sid,'\' GROUP BY b.Eid having Balance>=1
union(
Select b.BillNo EntryNo,b.Dt Dt,
if(b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount))=0,0,DateDiff(CURDATE(),b.DT)) `Days`,
b.Amount TotalAmount,0 SalesReturn,
if(Sum(a.Amount) is null,0,Sum(a.Amount)) Paid,b.Amount - if(Sum(a.Amount) is null,0,Sum(a.Amount)) Balance
From  opbalbill b LEFT OUTER JOIN Receiptbybill a on a.EntryNo=b.billno and b.lid=a.cid
where  b.lid=\'',Sid,'\' GROUP BY b.BillNo having Balance>=1)');
	PREPARE s1 FROM @qry;
    	EXECUTE s1;
    	DEALLOCATE PREPARE s1;

end
;;
DELIMITER ;

