-- ----------------------------
-- Procedure structure for `Sp_SareeReceiveDetails`
-- ----------------------------
DROP PROCEDURE IF EXISTS `Sp_SareeReceiveDetails`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_SareeReceiveDetails`(in EmpId bigint,in Macid bigint,
in WarpId bigint,in Eid bigint)
begin

	declare Cnt int default 0;

	
	set @qry=concat('select Count(*) into @Cnt From ReceiveDetails where Eid=\'',Eid,'\' ');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	
	if(@cnt>=1)then
		set @qry=concat('Select b.id Pid,b.name Name,Total,Issued,Issue,Shortage,Balance from  ReceiveDetails a,item_master b where Eid=\'',Eid,'\' and a.Pid=b.id');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	else
		set @qry=concat('select Count(*) into @Cnt From ReceiveDetails where EmpId=\'',EmpId,'\' and Macid=\'',MacId,'\' and WarpId=\'',WarpId,'\' 
		and close=0 ');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	
	if(@Cnt>=1)then

		set @qry=concat('Select c.id Pid,c.`Name` Item,a.Saree Total,Sum(Issue)+Sum(Shortage) Issued,0.00 Issue,Shortage,a.Saree-(Sum(Issue)+Sum(Shortage)) Balance
From warp_master a,item_master c,ReceiveDetails d ,machine e
where  d.WarpId=a.id and d.pid=c.id
and e.Id=d.MacId and close=0
and e.id=\'',MacId,'\' and a.id=\'',WarpId,'\'  and d.EmpId=\'',EmpId,'\'
GROUP BY c.id
');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	else
		set @qry=concat('Select c.id Pid,c.`Name` Item,a.Saree Total,0.00 Issued,0.00 Issue,0.00 Shortage,a.Saree Balance
From warp_master a,item_master c
where  a.id=\'',WarpId,'\'
and c.name=\'Saree\'
 order by c.id');
	
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	end if;
end if;
End
;;
DELIMITER ;

