DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Sp_WarpIssueDetails`(in EmpId bigint,in Macid bigint,
in WarpId bigint,in Eid bigint)
begin

	declare Cnt int default 0;

	
	set @qry=concat('select Count(*) into @Cnt From Issuedetails where Eid=\'',Eid,'\' ');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	
	if(@cnt>=1)then
		set @qry=concat('Select b.id Pid,b.name Name,Total,Issued,Issue,`Return`,Balance from  issuedetails a,item_master b where Eid=\'',Eid,'\' and a.Pid=b.id');
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		DEALLOCATE PREPARE s1;
	else
		set @qry=concat('select Count(*) into @Cnt From Issuedetails where EmpId=\'',EmpId,'\' and Macid=\'',MacId,'\' and WarpId=\'',WarpId,'\' and close=0 ');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	
	if(@Cnt>=1)then

		set @qry=concat('Select c.id Pid,c.`Name` Item,b.Qty Total,Sum(Issue)+Sum(`Return`) Issued,0.00 Issue,0.00 `Return`,b.Qty-(Sum(Issue)+Sum(`Return`)) Balance
From warp_master a,warp_details b,item_master c,issuedetails d ,machine e
where a.id=b.MasterId and b.ItemId=c.id 
and d.WarpId=a.id and d.pid=c.id
and e.Id=d.MacId and close=0
and e.id=\'',MacId,'\' and a.id=\'',WarpId,'\'  and d.EmpId=\'',EmpId,'\'
GROUP BY c.id
');
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	else
		set @qry=concat('Select c.id Pid,c.`Name` Item,b.Qty Total,0.00 Issued,0.00 Issue,0.00 `Return`,b.Qty Balance
From warp_master a,warp_details b,item_master c
where a.id=b.MasterId and b.ItemId=c.id and a.id=\'',WarpId,'\' order by c.id');
	
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	DEALLOCATE PREPARE s1;
	end if;
end if;
End
;;
DELIMITER ;

